#include "audio_detail.hpp"
#include <aibs/audio_codec.hpp>
namespace aibs {namespace {
using namespace audio_detail;
constexpr std::string_view magic="AIBAudio2";
void u32(std::vector<std::byte>& b,std::uint32_t n){for(unsigned s=0;s<32;s+=8)b.push_back(static_cast<std::byte>((n>>s)&255));}
void u64(std::vector<std::byte>& b,std::uint64_t n){for(unsigned s=0;s<64;s+=8)b.push_back(static_cast<std::byte>((n>>s)&255));}
void text(std::vector<std::byte>& b,const std::string& value){u32(b,static_cast<std::uint32_t>(value.size()));b.insert(b.end(),reinterpret_cast<const std::byte*>(value.data()),reinterpret_cast<const std::byte*>(value.data()+value.size()));}
struct Parsed{std::string_view id,name,source;std::uint32_t rate,channels;std::uint64_t frames;std::span<const std::byte> pcm;AudioCaptionReview review;std::uint32_t count;std::span<const std::byte> caption_data;};
Parsed parse(std::span<const std::byte> body){
 Reader r{body};const auto id=r.text(36),name=r.text(128),source=r.text(64);identity(id,source);label(name);const auto rate=r.u32(),channels=r.u32(),bits=r.u32(),reserved=r.u32();need(bits==16&&reserved==0,"Unknown audio encoding/reserved field");const auto frames=r.u64(),bytes=r.u64();need(bytes<=audio_asset_maximum_payload_bytes&&bytes<=r.data.size(),"Audio PCM byte count exceeds input/profile");const auto pcm=r.take(static_cast<std::size_t>(bytes));format(rate,channels,frames,pcm.size());const auto review=r.u32(),count=r.u32();need(review<=1&&count<=audio_asset_maximum_captions,"Audio caption review/count outside profile");const auto caption_data=r.data;need(count<=r.data.size()/20,"Audio caption records exceed remaining input");std::size_t texts=0,decoded=add(scanned_decoded(id.size(),name.size(),source.size(),pcm.size()),count*sizeof(AudioCaption));std::uint64_t previous=0;
 for(std::uint32_t i=0;i<count;++i){const auto begin=r.u64(),end=r.u64();const auto text=r.text(audio_asset_maximum_caption_text_bytes);texts=add(texts,text.size());need(texts<=audio_asset_maximum_caption_text_bytes&&begin>=previous&&begin<end&&end<=frames,"Audio caption range/text aggregate invalid");caption_text(text);previous=end;decoded=add(decoded,add(std::max<std::size_t>(15,text.size()),1));need(decoded<=audio_asset_maximum_decoded_bytes,"Audio caption decoded storage exceeds64MiB");}
 need(r.data.empty(),"Trailing audio body bytes");need(add(payload_cost(id.size(),name.size(),source.size(),pcm.size()),add(count*20,texts))<=audio_asset_maximum_payload_bytes&&decoded<=audio_asset_maximum_decoded_bytes,"Audio complete decoded storage exceeds profile");return {id,name,source,rate,channels,frames,pcm,static_cast<AudioCaptionReview>(review),count,caption_data};
}
}
std::vector<std::byte> encode_audio_asset(const AudioAsset& a){
 validate_audio_asset(a);const auto cost=audio_asset_cost(a);std::vector<std::byte> result;result.reserve(cost.payload_bytes);for(char c:magic)result.push_back(static_cast<std::byte>(c));for(unsigned n=0;n<3;++n)result.push_back(std::byte{});u32(result,2);u32(result,static_cast<std::uint32_t>(cost.payload_bytes-52));result.insert(result.end(),32,std::byte{});text(result,a.asset_id);text(result,a.name);text(result,a.source_sha256);u32(result,a.sample_rate);u32(result,a.channels);u32(result,16);u32(result,0);u64(result,a.frame_count);u64(result,a.pcm.size());result.insert(result.end(),a.pcm.begin(),a.pcm.end());u32(result,static_cast<std::uint32_t>(a.caption_review));u32(result,static_cast<std::uint32_t>(a.captions.size()));for(const auto& c:a.captions){u64(result,c.start_frame);u64(result,c.end_frame);text(result,c.text);}need(result.size()==cost.payload_bytes,"Audio encoder accounting mismatch");const auto checksum=digest(std::span<const std::byte>(result).subspan(52));std::copy(checksum.begin(),checksum.end(),result.begin()+20);return result;
}
AudioAsset decode_audio_asset(std::span<const std::byte> input){
 need(input.size()>=52&&input.size()<=audio_asset_maximum_payload_bytes,"Audio payload outside complete48MiB limit");Reader r{input};need(tag(r.take(9),magic),"Unsupported audio magic");for(auto b:r.take(3))need(b==std::byte{},"Unknown audio header reserved flags");need(r.u32()==2,"Unsupported audio payload version");need(r.u32()==input.size()-52,"Audio body length differs from exact input");const auto checksum=r.take(32);const auto actual=digest(r.data);need(std::equal(checksum.begin(),checksum.end(),actual.begin()),"Audio payload checksum differs");const auto p=parse(r.data);AudioAsset out;out.asset_id=p.id;out.name=p.name;out.source_sha256=p.source;out.sample_rate=p.rate;out.channels=p.channels;out.frame_count=p.frames;out.pcm.assign(p.pcm.begin(),p.pcm.end());out.caption_review=p.review;out.captions.reserve(p.count);Reader captions{p.caption_data};for(std::uint32_t i=0;i<p.count;++i){AudioCaption c;c.start_frame=captions.u64();c.end_frame=captions.u64();c.text=captions.text(audio_asset_maximum_caption_text_bytes);out.captions.push_back(std::move(c));}validate_audio_asset(out);return out;
}
}
